14	
15	using namespace AscendC;
16	
17	constexpr uint32_t BLOCK_SIZE = 32;
18	constexpr uint32_t BUFFER_NUM = 2;
19	constexpr uint32_t TILE_LENGTH = 128;
20	constexpr uint32_t OUT_UB_SIZE = 1024 * 45;
21	constexpr int32_t BITS_PER_BYTE = 8;
22	constexpr int32_t TRANS_RATIO = 32 / sizeof(int32_t);
23	constexpr uint32_t INT32_SIZE = sizeof(int32_t);
24	
25	template <typename T> class CustomizeBlockCopy {
26	public:
27	    __aicore__ inline CustomizeBlockCopy() {}
28	
29	    __aicore__ inline void Init(GM_ADDR kCache, GM_ADDR vCache, GM_ADDR srcBlockIndices, GM_ADDR dstBlockIndices,
30	                                GM_ADDR cumSum, AtbOps::CustomizeBlockCopyTilingData *tiling_data, TPipe *pipeIn)
31	    {
32	        InitParams(tiling_data);
33	        kCacheGm.SetGlobalBuffer((__gm__ T *)kCache, blockCount_ * blockSizeinElement_);
34	        vCacheGm.SetGlobalBuffer((__gm__ T *)vCache, blockCount_ * blockSizeinElement_);
35	        srcBlockIndicesGm.SetGlobalBuffer((__gm__ int32_t *)srcBlockIndices, sourceCount_);
36	        dstBlockIndicesGm.SetGlobalBuffer((__gm__ int32_t *)dstBlockIndices, destinationCount_);
37	        cumSumGm.SetGlobalBuffer((__gm__ int32_t *)cumSum, sourceCount_);
38	
39	        pipe = pipeIn;
40	        pipe->InitBuffer(inQueueX, BUFFER_NUM, TILE_LENGTH * INT32_SIZE);
41	        pipe->InitBuffer(inQueueY, BUFFER_NUM, TILE_LENGTH * INT32_SIZE);
42	        pipe->InitBuffer(inQueueA, BUFFER_NUM, TILE_LENGTH * INT32_SIZE);
43	        pipe->InitBuffer(onesBuf, TILE_LENGTH * INT32_SIZE);
44	        pipe->InitBuffer(floatBuf, TILE_LENGTH * INT32_SIZE);
45	        pipe->InitBuffer(positionBuf, TILE_LENGTH * INT32_SIZE);
46	        pipe->InitBuffer(maskBuf, TILE_LENGTH / BITS_PER_BYTE);
47	        pipe->InitBuffer(src2dstQueueK, BUFFER_NUM, OUT_UB_SIZE);
48	        pipe->InitBuffer(src2dstQueueV, BUFFER_NUM, OUT_UB_SIZE);
49	    }
50	
51	    __aicore__ inline void Process()
52	    {
53	        int32_t loopCount = (sourceCount_ + TILE_LENGTH - 1) / TILE_LENGTH;
54	        int32_t tailLength = sourceCount_ % TILE_LENGTH;
55	        if (tailLength == 0) {
56	            tailLength = TILE_LENGTH;
57	        }
58	        for (int32_t i = 0; i < loopCount - 1; i++) {
59	            if (cumSumOffset_ >= 0) {
60	                break;
61	            }
62	            SearchCopyIn(i, TILE_LENGTH);
63	            SearchCompute(i, TILE_LENGTH);
64	        }
65	        if (cumSumOffset_ < 0) {
66	            SearchCopyIn(loopCount - 1, tailLength);
67	            SearchCompute(loopCount - 1, tailLength);
68	        }
69	
70	        loopCount = (perCoreCopyCount_ + TILE_LENGTH - 1) / TILE_LENGTH;
71	        tailLength = perCoreCopyCount_ % TILE_LENGTH;
72	        if (tailLength == 0) {
73	            tailLength = TILE_LENGTH;
74	        }
75	        for (int32_t i = 0; i < loopCount - 1; i++) {
76	            CopyIndicesIn(i, TILE_LENGTH);
77	            CopyBlocks(i, TILE_LENGTH);
78	        }
79	        CopyIndicesIn(loopCount - 1, tailLength);
80	        CopyBlocks(loopCount - 1, tailLength);
81	    }
82	
83	private:
84	    __aicore__ inline void InitParams(AtbOps::CustomizeBlockCopyTilingData *tiling_data)
85	    {
86	        blockIdx_ = GetBlockIdx();
87	        if (blockIdx_ == 0) {
88	            cumSumOffset_ = 0;
89	        }
90	        perCoreCopyCount_ = tiling_data->perCoreCopyCount;
91	        tailCoreCopyCount_ = tiling_data->tailCoreCopyCount;
92	        if (blockIdx_ < tailCoreCopyCount_) {
93	            perCoreCopyCount_++;
94	            gmOffset_ = perCoreCopyCount_ * blockIdx_;
95	        } else {
96	            gmOffset_ = perCoreCopyCount_ * blockIdx_ + tailCoreCopyCount_;
97	        }
98	        blockCount_ = tiling_data->blockCount;
99	        blockSizeinElement_ = static_cast<uint64_t>(tiling_data->blockSize) * tiling_data->numHead * tiling_data->headSizeK;
100	        sourceCount_ = tiling_data->sourceCount;
101	        destinationCount_ = tiling_data->destinationCount;
102	        typeByte_ = tiling_data->typeByte;
103	        blockDim_ = tiling_data->blockDim;
104	        outUbLength_ = OUT_UB_SIZE / typeByte_;
105	        cacheCopyLoopCount_ = (blockSizeinElement_ + outUbLength_ - 1) / outUbLength_;
106	        cacheCopyTailLength_ = blockSizeinElement_ % outUbLength_;
107	        if (cacheCopyTailLength_ == 0) {
108	            cacheCopyTailLength_ = outUbLength_;
109	        }
110	    }
111	
112	    __aicore__ inline void SearchCopyIn(int32_t progress, int32_t processLength)
113	    {
114	        LocalTensor<int32_t> cumSumLocal = inQueueX.AllocTensor<int32_t>();
115	        int32_t processDataSizeResidual = processLength % TRANS_RATIO;
116	        if (processDataSizeResidual == 0) {
117	            DataCopy(cumSumLocal, cumSumGm[progress * TILE_LENGTH], processLength);
118	        } else {
119	            int32_t paddingLength = TRANS_RATIO - processDataSizeResidual;
120	            DataCopyExtParams copyParams{1, static_cast<uint32_t>(processLength * INT32_SIZE), 0, 0, 0};
121	            DataCopyPadExtParams<int32_t> padParams{true, 0, static_cast<uint8_t>(paddingLength), INT32_MAX};
122	            DataCopyPad(cumSumLocal, cumSumGm[progress * TILE_LENGTH], copyParams, padParams);
123	        }
124	        inQueueX.EnQue(cumSumLocal);
125	    }
126	
127	    __aicore__ inline void SearchCompute(int32_t progress, int32_t processLength)
128	    {
129	        LocalTensor<int32_t> cumSumLocal = inQueueX.DeQue<int32_t>();
130	        LocalTensor<uint8_t> maskLocal = maskBuf.Get<uint8_t>();
131	        LocalTensor<float> onesLocal = onesBuf.Get<float>();
132	        LocalTensor<float> positionLocal = positionBuf.Get<float>();
133	        int32_t processLengthPad = (processLength + TRANS_RATIO - 1) / TRANS_RATIO * TRANS_RATIO;
134	        event_t eventIDMTE2ToS = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE2_S));
135	        SetFlag<HardEvent::MTE2_S>(eventIDMTE2ToS);
136	        WaitFlag<HardEvent::MTE2_S>(eventIDMTE2ToS);
137	        Duplicate(cumSumLocal[processLengthPad], INT32_MAX, TILE_LENGTH - processLengthPad);
138	        Duplicate(onesLocal, static_cast<float>(1), TILE_LENGTH);
139	        int32_t endCum = cumSumLocal.GetValue(processLength - 1);
140	        if (gmOffset_ < endCum) {
141	            LocalTensor<float> cumSumLocalFloat = floatBuf.Get<float>();
142	            Cast(cumSumLocalFloat, cumSumLocal, RoundMode::CAST_FLOOR, TILE_LENGTH);
143	            PipeBarrier<PIPE_V>();
144	            CompareScalar(maskLocal, cumSumLocalFloat, static_cast<float>(gmOffset_), CMPMODE::LE, TILE_LENGTH);
145	            PipeBarrier<PIPE_V>();
146	            Select(positionLocal, maskLocal, onesLocal, static_cast<float>(0), SELMODE::VSEL_TENSOR_SCALAR_MODE,
147	                   TILE_LENGTH);
148	            PipeBarrier<PIPE_V>();
149	            ReduceSum(positionLocal, positionLocal, onesLocal, TILE_LENGTH);
150	            event_t eventIDVToS = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::V_S));
151	            SetFlag<HardEvent::V_S>(eventIDVToS);
152	            WaitFlag<HardEvent::V_S>(eventIDVToS);
153	            cumSumOffset_ = progress * TILE_LENGTH + positionLocal.GetValue(0);
154	        }
155	        inQueueX.FreeTensor(cumSumLocal);
156	    }
157	
158	    __aicore__ inline void CopyIndicesIn(int32_t progress, int32_t processLength)
159	    {
160	        LocalTensor<int32_t> dstBlockIndicesLocal = inQueueY.AllocTensor<int32_t>();
161	        LocalTensor<int32_t> srcBlockIndicesLocal = inQueueX.AllocTensor<int32_t>();
162	        LocalTensor<int32_t> cumSumLocal = inQueueA.AllocTensor<int32_t>();
163	        int32_t cumSumProcessLength =
164	            ((sourceCount_ - cumSumOffset_) < processLength ? (sourceCount_ - cumSumOffset_) : processLength);
165	        DataCopyExtParams copyParams{1, static_cast<uint32_t>(processLength * INT32_SIZE), 0, 0, 0};
166	        DataCopyPadExtParams<int32_t> padParams{false, 0, static_cast<uint8_t>(0), 0};
167	        DataCopyExtParams copyParams1{1, static_cast<uint32_t>(cumSumProcessLength * INT32_SIZE), 0, 0, 0};
168	        DataCopyPad(cumSumLocal, cumSumGm[cumSumOffset_], copyParams1, padParams);
169	        DataCopyPad(srcBlockIndicesLocal, srcBlockIndicesGm[cumSumOffset_], copyParams1, padParams);
170	        DataCopyPad(dstBlockIndicesLocal, dstBlockIndicesGm[gmOffset_ + progress * TILE_LENGTH], copyParams, padParams);
171	        inQueueY.EnQue(dstBlockIndicesLocal);
172	        inQueueX.EnQue(srcBlockIndicesLocal);
173	        inQueueA.EnQue(cumSumLocal);
174	    }
175	
176	    __aicore__ inline void CopyBlocks(int32_t progress, int32_t processLength)
177	    {
178	        LocalTensor<int32_t> dstBlockIndicesLocal = inQueueY.DeQue<int32_t>();
179	        LocalTensor<int32_t> srcBlockIndicesLocal = inQueueX.DeQue<int32_t>();
180	        LocalTensor<int32_t> cumSumLocal = inQueueA.DeQue<int32_t>();
181	        event_t eventIDMTE2ToS = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE2_S));
182	        SetFlag<HardEvent::MTE2_S>(eventIDMTE2ToS);
183	        int32_t processIndex = 0;
184	        int32_t completedCount = 0;
185	        int64_t previousCum = gmOffset_ + progress * TILE_LENGTH;
186	        WaitFlag<HardEvent::MTE2_S>(eventIDMTE2ToS);
187	        while (completedCount < processLength) {
188	            int32_t srcBlockIndex = srcBlockIndicesLocal.GetValue(processIndex);
189	            int64_t currentCum = static_cast<int64_t>(cumSumLocal.GetValue(processIndex));
190	            // 在当前核处理范围内，源block地址srcBlockIndex对应的目标block地址数量
191	            int32_t paddingCount = (currentCum - previousCum) > (processLength - completedCount) ?
192	                                       (processLength - completedCount) :
193	                                       (currentCum - previousCum);
194	            if (currentCum - previousCum <= processLength - completedCount) {
195	                // 在当前核处理范围内，源block地址srcBlockIndex对应的目标block地址已处理完，考虑下一个源block地址
196	                processIndex++;
197	            }
198	            previousCum = currentCum;
199	            CopyOneSrc2MultiDst(srcBlockIndex, completedCount, paddingCount, dstBlockIndicesLocal);
200	            completedCount += paddingCount;
201	        }
202	        cumSumOffset_ += processIndex;
203	        inQueueA.FreeTensor(cumSumLocal);
204	        inQueueX.FreeTensor(srcBlockIndicesLocal);
205	        inQueueY.FreeTensor(dstBlockIndicesLocal);
206	    }
207	
208	    __aicore__ inline void CopyOneSrc2MultiDst(int32_t srcBlockIndex, int32_t completedCount, int32_t paddingCount,
209	                                               LocalTensor<int32_t> &dstIndices)
210	    {
211	        for (int i = 0; i < paddingCount; i++) {
212	            int32_t dstBlockIndex = dstIndices.GetValue(completedCount + i);
213	            event_t eventIDSToMTE2 = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::S_MTE2));
214	            SetFlag<HardEvent::S_MTE2>(eventIDSToMTE2);
215	            WaitFlag<HardEvent::S_MTE2>(eventIDSToMTE2);
216	            for (int32_t j = 0; j < cacheCopyLoopCount_ - 1; j++) {
217	                CopyOneBlockIn(srcBlockIndex, j, outUbLength_);
218	                CopyOneBlockOut(dstBlockIndex, j, outUbLength_);
219	            }
220	            CopyOneBlockIn(srcBlockIndex, cacheCopyLoopCount_ - 1, cacheCopyTailLength_);
221	            CopyOneBlockOut(dstBlockIndex, cacheCopyLoopCount_ - 1, cacheCopyTailLength_);
222	        }
223	    }
224	
225	    __aicore__ inline void CopyOneBlockIn(int32_t srcBlockIndex, int32_t progress, int32_t processLength)
226	    {
227	        LocalTensor<T> src2dstLocalK = src2dstQueueK.AllocTensor<T>();
228	        LocalTensor<T> src2dstLocalV = src2dstQueueV.AllocTensor<T>();
229	        DataCopyExtParams copyParams{1, static_cast<uint32_t>(processLength * typeByte_), 0, 0, 0};
230	        DataCopyPadExtParams<T> padParams{false, 0, static_cast<uint8_t>(0), 0};
231	        DataCopyPad(src2dstLocalK, kCacheGm[srcBlockIndex * blockSizeinElement_ + progress * outUbLength_], copyParams,
232	                    padParams);
233	        DataCopyPad(src2dstLocalV, vCacheGm[srcBlockIndex * blockSizeinElement_ + progress * outUbLength_], copyParams,
234	                    padParams);
235	        src2dstQueueK.EnQue(src2dstLocalK);
236	        src2dstQueueV.EnQue(src2dstLocalV);
237	    }
238	
239	    __aicore__ inline void CopyOneBlockOut(int32_t dstBlockIndex, int32_t progress, int32_t processLength)
240	    {
241	        LocalTensor<T> src2dstLocalK = src2dstQueueK.DeQue<T>();
242	        LocalTensor<T> src2dstLocalV = src2dstQueueV.DeQue<T>();
243	        DataCopyExtParams copyParams{1, static_cast<uint32_t>(processLength * typeByte_), 0, 0, 0};
244	        DataCopyPad(kCacheGm[dstBlockIndex * blockSizeinElement_ + progress * outUbLength_], src2dstLocalK, copyParams);
245	        DataCopyPad(vCacheGm[dstBlockIndex * blockSizeinElement_ + progress * outUbLength_], src2dstLocalV, copyParams);
246	        src2dstQueueK.FreeTensor(src2dstLocalK);
247	        src2dstQueueV.FreeTensor(src2dstLocalV);
248	    }
249	
250	private:
251	    TPipe *pipe;
252	
253	    GlobalTensor<T> kCacheGm;
254	    GlobalTensor<T> vCacheGm;
255	    GlobalTensor<int32_t> srcBlockIndicesGm;
256	    GlobalTensor<int32_t> dstBlockIndicesGm;
257	    GlobalTensor<int32_t> cumSumGm;
258	    GlobalTensor<int32_t> srcWorkSpaceGm;
259	    GlobalTensor<int32_t> syncGm;
260	
261	    TQue<QuePosition::VECIN, BUFFER_NUM> inQueueX;
262	    TQue<QuePosition::VECIN, BUFFER_NUM> inQueueY;
263	    TQue<QuePosition::VECIN, BUFFER_NUM> inQueueA;
264	    TBuf<TPosition::VECCALC> maskBuf;
265	    TBuf<TPosition::VECCALC> onesBuf;
266	    TBuf<TPosition::VECCALC> positionBuf;
267	    TBuf<TPosition::VECCALC> floatBuf;
268	    TQueBind<QuePosition::VECIN, QuePosition::VECOUT, BUFFER_NUM> src2dstQueueK;
269	    TQueBind<QuePosition::VECIN, QuePosition::VECOUT, BUFFER_NUM> src2dstQueueV;
270	
271	    uint32_t perCoreCopyCount_ = 0;
272	    uint32_t tailCoreCopyCount_ = 0;
273	    uint32_t blockIdx_ = 0;
274	    uint32_t blockCount_;
275	    uint32_t sourceCount_;
276	    uint32_t destinationCount_;
277	    uint32_t typeByte_;
278	    uint32_t blockDim_;
279	    uint32_t outUbLength_ = 0;
280	    uint32_t cacheCopyLoopCount_ = 0;
281	    uint32_t cacheCopyTailLength_ = 0;
282	    uint64_t blockSizeinElement_;
283	    int64_t gmOffset_ = 0;
284	    int64_t cumSumOffset_ = -1;
285	};
286	
287	inline __aicore__ void InitTilingData(const __gm__ uint8_t *p_tilingdata,
288	                                      AtbOps::CustomizeBlockCopyTilingData *tilingdata)
289	{
290	#if defined(__CCE_KT_TEST__) || (__CCE_AICORE__ == 220)
291	    tilingdata->blockCount = (*(const __gm__ uint32_t *)(p_tilingdata + 0));
292	    tilingdata->blockSize = (*(const __gm__ uint32_t *)(p_tilingdata + 4));
293	    tilingdata->numHead = (*(const __gm__ uint32_t *)(p_tilingdata + 8));
294	    tilingdata->headSizeK = (*(const __gm__ uint32_t *)(p_tilingdata + 12));
295	    tilingdata->headSizeV = (*(const __gm__ uint32_t *)(p_tilingdata + 16));
296	    tilingdata->sourceCount = (*(const __gm__ uint32_t *)(p_tilingdata + 20));
297	    tilingdata->destinationCount = (*(const __gm__ uint32_t *)(p_tilingdata + 24));
298	    tilingdata->typeByte = (*(const __gm__ uint32_t *)(p_tilingdata + 28));
299	    tilingdata->blockDim = (*(const __gm__ uint32_t *)(p_tilingdata + 32));
300	    tilingdata->perCoreCopyCount = (*(const __gm__ uint32_t *)(p_tilingdata + 36));
301	    tilingdata->tailCoreCopyCount = (*(const __gm__ uint32_t *)(p_tilingdata + 40));
302	#endif
303	}
304	
305	extern "C" __global__ __aicore__ void customize_blockcopy(GM_ADDR kCache, GM_ADDR vCache, GM_ADDR srcBlockIndices,
306	                                                          GM_ADDR dstBlockIndices, GM_ADDR cumSum, GM_ADDR kCacheOut,
307	                                                          GM_ADDR vCacheOut, GM_ADDR tiling)
308	{
309	    AtbOps::CustomizeBlockCopyTilingData tilingData;
310	    InitTilingData(tiling, &(tilingData));
311	    TPipe pipe;
312	    if (TILING_KEY_IS(100000000)) {
313	        CustomizeBlockCopy<int8_t> op;
314	        op.Init(kCache, vCache, srcBlockIndices, dstBlockIndices, cumSum, &tilingData, &pipe);
315	        op.Process();
316	    }
317	    if (TILING_KEY_IS(200000000)) {
318	        CustomizeBlockCopy<half> op;
319	        op.Init(kCache, vCache, srcBlockIndices, dstBlockIndices, cumSum, &tilingData, &pipe);
320	        op.Process();
321	    }
322	}
