7	 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
8	 * See LICENSE in the root of the software repository for the full text of the License.
9	 */
10	
11	#include "customize_blockcopy_tiling.h"
12	#include <mki/utils/assert/assert.h>
13	#include <mki/utils/log/log.h>
14	#include <mki/utils/math/math.h>
15	#include <mki/utils/platform/platform_info.h>
16	#include "customize_blockcopy/kernel_implement/include/customizeblockcopy.h"
17	#include "tiling_data.h"
18	static constexpr int32_t NZ_SIZE = 16;
19	static constexpr uint64_t BLOCKCOPY_WKSP_TENSOR_IDX = 7;
20	static constexpr uint64_t BLOCKCOPY_SYNC_WORKSPACE_TENSOR_IDX = 8;
21	static constexpr int32_t BYTES_32 = 32;
22	namespace AtbOps {
23	using namespace Mki;
24	/**
25	 * @brief 针对“ND”格式的 K/V Cache 计算 tilingData。
26	 *
27	 * “ND”格式：Tensor 形状为 [B, blockSize, numHead, headSize]。
28	 * 本函数读取输入维度并校验合法性，然后填充 blockSize、numHead、
29	 * headSizeK、headSizeV 等字段到 tilingData 中。
30	 *
31	 * @param[in]  launchParam   运行时输入信息
32	 * @param[out] kernelInfo    填充后的 kernelInfo，其中包含 tilingData
33	 * @return bool              成功返回 true，失败返回 false
34	 */
35	bool BlockCopyTilingNd(const LaunchParam &launchParam, KernelInfo &kernelInfo)
36	{
37	    CustomizeBlockCopyTilingData *tilingDataPtr =
38	        reinterpret_cast<AtbOps::CustomizeBlockCopyTilingData *>(kernelInfo.GetTilingHostAddr());
39	    MKI_CHECK(tilingDataPtr != nullptr, "tilingHost should not be empty", return false);
40	    auto &kShape = launchParam.GetInTensor(0).desc.dims;
41	    auto &vShape = launchParam.GetInTensor(1).desc.dims;
42	    // 910B kv shape [#B, B, head, DIM]
43	    uint32_t blockSize = static_cast<uint32_t>(kShape.at(1));
44	    uint32_t numHead = static_cast<uint32_t>(kShape.at(2));
45	    uint32_t headSizeK = static_cast<uint32_t>(kShape.at(3));
46	    uint32_t headSizeV = static_cast<uint32_t>(vShape.at(3));
47	    MKI_CHECK(blockSize > 0, "blockSize is invalid", return false);
48	    MKI_CHECK(numHead > 0, "numHead is invalid", return false);
49	    tilingDataPtr->blockSize = blockSize;
50	    tilingDataPtr->numHead = numHead;
51	    MKI_CHECK(headSizeK > 0, "headSizeK is invalid", return false);
52	    MKI_CHECK(headSizeV > 0, "headSizeV is invalid", return false);
53	    tilingDataPtr->headSizeK = headSizeK;
54	    tilingDataPtr->headSizeV = headSizeV;
55	    return true;
56	}
57	/**
58	 * @brief 针对“NZ”格式的 K/V Cache 计算 tilingData。
59	 *
60	 * “NZ”格式：310P 特殊布局，Tensor 形状为
61	 * [B, head*headSize/16, blockSize, 16]，
62	 * 并强制 numHead=1。根据 dim1*16 计算 headSizeK/V。
63	 *
64	 * @param[in]  launchParam   运行时输入信息
65	 * @param[out] kernelInfo    填充后的 kernelInfo，其中包含 tilingData
66	 * @return bool              成功返回 true，失败返回 false
67	 */
68	bool BlockCopyTilingNz(const LaunchParam &launchParam, KernelInfo &kernelInfo)
69	{
70	    CustomizeBlockCopyTilingData *tilingDataPtr =
71	        reinterpret_cast<AtbOps::CustomizeBlockCopyTilingData *>(kernelInfo.GetTilingHostAddr());
72	    MKI_CHECK(tilingDataPtr != nullptr, "tilingHost should not be empty", return false);
73	    auto &kShape = launchParam.GetInTensor(0).desc.dims;
74	    auto &vShape = launchParam.GetInTensor(1).desc.dims;
75	    // nz：无法获取头和头大小；numhead弃置，改用headSizeV来保存大小
76	    // 310p的kv：[#B, head*head_size // 16, B, 16]
77	    uint32_t blockSize = static_cast<uint32_t>(kShape.at(2));
78	    // 头参数固定设置为1
79	    uint32_t numHead = static_cast<uint32_t>(1);
80	    uint32_t headSizeK = static_cast<uint32_t>(kShape.at(1) * NZ_SIZE);
81	    uint32_t headSizeV = static_cast<uint32_t>(vShape.at(1) * NZ_SIZE);
82	    MKI_CHECK(blockSize > 0, "blockSize is invalid", return false);
83	    MKI_CHECK(numHead > 0, "numHead is invalid", return false);
84	    MKI_CHECK(headSizeK > 0, "headSizeK is invalid", return false);
85	    MKI_CHECK(headSizeV > 0, "headSizeV is invalid", return false);
86	    tilingDataPtr->blockSize = blockSize;
87	    tilingDataPtr->numHead = numHead;
88	    tilingDataPtr->headSizeK = headSizeK;
89	    tilingDataPtr->headSizeV = headSizeV;
90	    return true;
91	}
92	/**
93	 * @brief 仅在 310P 平台上检查 K/V Cache 总元素数是否与 typeByte 对齐。
94	 *
95	 * 防止后续的 vector 访问越界，要求按 32 字节对齐。
96	 *
97	 * @param[in]  launchParam   运行时输入信息
98	 * @param[out] kernelInfo    kernel 调度信息（仅读取 tilingData）
99	 * @return bool              对齐检查通过返回 true，否则返回 false
100	 */
101	bool BlockCopyTilingCheck310P(const LaunchParam &launchParam, KernelInfo &kernelInfo)
102	{
103	    TensorDType inDtype = launchParam.GetInTensor(0).desc.dtype;
104	    uint32_t typeByte = static_cast<uint32_t>(GetTensorElementSize(inDtype));
105	    CustomizeBlockCopyTilingData *tilingDataPtr =
106	        reinterpret_cast<AtbOps::CustomizeBlockCopyTilingData *>(kernelInfo.GetTilingHostAddr());
107	    MKI_CHECK(tilingDataPtr != nullptr, "tilingHost should not be empty", return false);
108	    auto headDim = tilingDataPtr->blockSize * tilingDataPtr->numHead;
109	    auto totalKCacheItems = tilingDataPtr->headSizeK * headDim;
110	    auto totalVCacheItems = tilingDataPtr->headSizeV * headDim;
111	    MKI_CHECK(totalKCacheItems % typeByte == 0, "310P Platform KCache should be aligned with 32 bytes!", return false);
112	    MKI_CHECK(totalVCacheItems % typeByte == 0, "310P Platform VCache should be aligned with 32 bytes!", return false);
113	    return true;
114	}
115	
116	Status CustomizeBlockCopyTiling(const LaunchParam &launchParam, KernelInfo &kernelInfo)
117	{
118	    auto param = AnyCast<OpParam::CustomizeBlockCopy>(launchParam.GetParam());
119	    auto &kShape = launchParam.GetInTensor(0).desc.dims;
120	    auto &srcShape = launchParam.GetInTensor(2).desc.dims;
121	    auto &dstShape = launchParam.GetInTensor(3).desc.dims;
122	    auto &cumShape = launchParam.GetInTensor(4).desc.dims;
123	    uint32_t blockCount = static_cast<uint32_t>(kShape.at(0));
124	    uint32_t sourceCount = static_cast<uint32_t>(srcShape.at(0));
125	    uint32_t destinationCount = static_cast<uint32_t>(dstShape.at(0));
126	    uint32_t cumSumCount = static_cast<uint32_t>(cumShape.at(0));
127	
128	    if (param.type == OpParam::CustomizeBlockCopy::BLOCK_COPY_CACHE_ND) {
129	        MKI_CHECK(BlockCopyTilingNd(launchParam, kernelInfo), "K/V Cache size is invalid",
130	                  return Status::FailStatus(ERROR_INVALID_VALUE));
131	    } else {
132	        MKI_CHECK(BlockCopyTilingNz(launchParam, kernelInfo), "K/V Cache size is invalid",
133	                  return Status::FailStatus(ERROR_INVALID_VALUE));
134	    }
135	    bool is310P = PlatformInfo::Instance().GetPlatformType() == PlatformType::ASCEND_310P ? true : false;
136	    if (is310P) {
137	        MKI_CHECK(BlockCopyTilingCheck310P(launchParam, kernelInfo), "K/V Cache size aligned error in 310P",
138	                  return Status::FailStatus(ERROR_INVALID_VALUE));
139	    }
140	
141	    MKI_CHECK(launchParam.GetParam().Type() == typeid(OpParam::CustomizeBlockCopy), "OpParam is invalid",
142	              return Status::FailStatus(ERROR_INFERSHAPE_ERROR));
143	    MKI_CHECK(sourceCount > 0, "sourceCount is invalid", return Status::FailStatus(ERROR_INVALID_VALUE));
144	    MKI_CHECK(destinationCount > 0, "destinationCount is invalid", return Status::FailStatus(ERROR_INVALID_VALUE));
145	    MKI_CHECK(blockCount > 0, "blockCount is invalid", return Status::FailStatus(ERROR_INVALID_VALUE));
146	    MKI_CHECK(sourceCount == cumSumCount, "src&cum's shape must be same ",
147	              return Status::FailStatus(ERROR_INVALID_VALUE));
148	
149	    CustomizeBlockCopyTilingData *tilingDataPtr =
150	        reinterpret_cast<AtbOps::CustomizeBlockCopyTilingData *>(kernelInfo.GetTilingHostAddr());
151	    MKI_CHECK(tilingDataPtr != nullptr, "tilingHost should not be empty",
152	              return Status::FailStatus(ERROR_INVALID_VALUE, "tilingHost should not be empty"));
153	
154	    tilingDataPtr->blockCount = blockCount;
155	    tilingDataPtr->sourceCount = sourceCount;
156	    tilingDataPtr->destinationCount = destinationCount;
157	
158	    TensorDType inDtype = launchParam.GetInTensor(0).desc.dtype;
159	    uint32_t typeByte = static_cast<uint32_t>(GetTensorElementSize(inDtype));
160	    tilingDataPtr->typeByte = typeByte;
161	
162	    uint32_t tilingKey = TILING_DTYPE_IDX * typeByte;
163	
164	    uint64_t maxCore = static_cast<uint64_t>(PlatformInfo::Instance().GetCoreNum(CoreType::CORE_TYPE_VECTOR));
165	    uint32_t actualCore = destinationCount < maxCore ? destinationCount : maxCore;
166	
167	    tilingDataPtr->blockDim = actualCore;
168	
169	    tilingDataPtr->perCoreCopyCount = destinationCount / actualCore;
170	    tilingDataPtr->tailCoreCopyCount = destinationCount % actualCore;
171	
172	    MKI_LOG(INFO) << "blockCount: " << blockCount << ", sourceCount: " << sourceCount
173	                  << ", destinationCount: " << destinationCount;
174	    kernelInfo.SetBlockDim(actualCore);
175	    kernelInfo.SetTilingId(tilingKey);
176	    return Status::OkStatus();
177	}
178	} // namespace AtbOps
