11	#include <mki/base/operation_base.h>
12	#include <mki/utils/log/log.h>
13	#include <mki/utils/const/op_const.h>
14	#include <mki_loader/op_register.h>
15	#include <mki/utils/checktensor/check_tensor.h>
16	#include "include/customizeblockcopy.h"
17	
18	
19	namespace AtbOps {
20	using namespace Mki;
21	/**
22	 * @class CustomizeBlockCopyOperation
23	 * @brief Mki 层的自定义 CustomizeBlockCopy 算子，实现参数检查、形状推理及 Kernel 选择。
24	 */
25	class CustomizeBlockCopyOperation : public OperationBase {
26	public:
27	    explicit CustomizeBlockCopyOperation(const std::string &opName) noexcept : OperationBase(opName) {}
28	    /**
29	     * @brief 返回算子期望的输入张量数量。
30	     * @param[in] specificParam  包含 op 参数的 Any 对象，应为 OpParam::CustomizeBlockCopy 类型。
31	     * @return int64_t          固定返回 5；检查失败时返回 0。
32	     */
33	    int64_t GetInputNum(const Any &specificParam) const override
34	    {
35	        MKI_CHECK(specificParam.Type() == typeid(OpParam::CustomizeBlockCopy), "OpParam is invalid", return 0);
36	        return DIM_5;
37	    }
38	    /**
39	     * @brief 返回算子期望的输出张量数量。
40	     * @param[in] specificParam  包含 op 参数的 Any 对象，应为 OpParam::CustomizeBlockCopy 类型。
41	     * @return int64_t          固定返回 2（in-place 返回 K/V）；检查失败时返回 0。
42	     */
43	    int64_t GetOutputNum(const Any &specificParam) const override
44	    {
45	        MKI_CHECK(specificParam.Type() == typeid(OpParam::CustomizeBlockCopy), "OpParam is invalid", return 0);
46	        return DIM_2;
47	    }
48	    /**
49	     * @brief 对 LaunchParam 中的参数和输入张量进行完整性检查。
50	     *
51	     * 依次校验：
52	     *  - Param 类型是否为 OpParam::CustomizeBlockCopy
53	     *  - 输入张量数量是否为 5
54	     *  - K/V Cache、src 索引、dst 索引列表格式是否合法
55	     *
56	     * @param[in] launchParam  包含运行时所有输入张量和参数的上下文
57	     * @return bool            全部检查通过返回 true，否则 false
58	     */
59	    bool CheckBlockCopy(const LaunchParam &launchParam) const
60	    {
61	        MKI_CHECK(launchParam.GetParam().Type() == typeid(OpParam::CustomizeBlockCopy), "OpParam is invalid",
62	                  return false);
63	
64	        MKI_CHECK(launchParam.GetInTensorCount() == 5, "input num invalid", return false);
65	
66	        return CheckKVCache(launchParam) && CheckSrcBlockList(launchParam) && CheckDistBlockIndices(launchParam);
67	    }
68	    /**
69	     * @brief 在推理阶段设置输出张量形状，同输入的 K/V Cache 保持一致。
70	     *
71	     * 1. 调用 CheckBlockCopy 检查参数合法性
72	     * 2. 将 inTensors[0]、inTensors[1] 直接赋值给 outTensors[0]、outTensors[1]
73	     *
74	     * @param[in]  launchParam   运行时输入张量及参数
75	     * @param[out] outTensors    填充后的输出张量列表
76	     * @return Status            成功返回 OkStatus；失败返回带错误码的 FailStatus
77	     */
78	    Status InferShapeImpl(const LaunchParam &launchParam, SVector<Tensor> &outTensors) const override
79	    {
80	        MKI_CHECK(CheckBlockCopy(launchParam), "Failed to check launch param",
81	                  return Status::FailStatus(ERROR_INFERSHAPE_ERROR, "Failed to check launch param"));
82	
83	        auto &keyCacheIn = launchParam.GetInTensor(DIM_0);
84	        auto &valueCacheIn = launchParam.GetInTensor(DIM_1);
85	        outTensors[DIM_0] = keyCacheIn;
86	        outTensors[DIM_1] = valueCacheIn;
87	        return Status::OkStatus();
88	    }
89	    /**
90	     * @brief 选择最合适的 Kernel 实例执行本操作。
91	     *
92	     * 1. 调用 IsConsistent 检查参数合法性和形状一致性
93	     * 2. 检查 Param 类型
94	     * 3. 返回名为 "CustomizeBlockCopyKernel" 的 Kernel 对象
95	     *
96	     * @param[in] launchParam  运行时输入张量及参数
97	     * @return Kernel*         成功返回指向 Kernel 的指针；失败返回 nullptr
98	     */
99	    Kernel *GetBestKernel(const LaunchParam &launchParam) const override
100	    {
101	        MKI_CHECK(IsConsistent(launchParam), "Failed to check consistent", return nullptr);
102	        MKI_CHECK(launchParam.GetParam().Type() == typeid(OpParam::CustomizeBlockCopy), "OpParam is invalid",
103	                  return nullptr);
104	        return GetKernelByName("CustomizeBlockCopyKernel");
105	    }
106	
107	private:
108	    /**
109	     * @brief 检查 K/V Cache 张量的合法性。
110	     *
111	     * - 非空且 dtype 相同
112	     * - dtype 为 float16、bfloat16 或 int8
113	     * - 维度数量为 4，且 shape 一致
114	     *
115	     * @param[in] launchParam  运行时上下文
116	     * @return bool            合法返回 true，否则 false
117	     */
118	    bool CheckKVCache(const LaunchParam &launchParam) const
119	    {
120	        auto &keyCache = launchParam.GetInTensor(DIM_0);   // K.shape = [block_count, block_size, num_heads, head_size]
121	        auto &valueCache = launchParam.GetInTensor(DIM_1); // V.shape = [block_count, block_size, num_heads, head_size]
122	
123	        MKI_CHECK(!CheckEmptyTensor(keyCache), "1st inTensor should not be null tensor ", return false);
124	        MKI_CHECK(!CheckEmptyTensor(valueCache), "2nd inTensor should not be null tensor ", return false);
125	
126	        auto inDtype = keyCache.desc.dtype;
127	        MKI_CHECK(valueCache.desc.dtype == inDtype, "K&V's dtype must be same", return false);
128	        MKI_CHECK(inDtype == TENSOR_DTYPE_FLOAT16 || inDtype == TENSOR_DTYPE_BF16 || inDtype == TENSOR_DTYPE_INT8,
129	                  "K&V should be both float16 OR int8 OR bfloat16", return false);
130	
131	        MKI_CHECK(keyCache.desc.dims == valueCache.desc.dims, "K&V's shape should be same", return false);
132	        MKI_CHECK(keyCache.desc.dims.size() == DIM_4, "K&V's dim num should be " << DIM_4, return false);
133	
134	        return true;
135	    }
136	    /**
137	     * @brief 检查 src block 列表及 cumSum 张量的合法性。
138	     *
139	     * - 非空
140	     * - dtype 为 int32
141	     * - shape/dims 与 cumSum 匹配
142	     *
143	     * @param[in] launchParam  运行时上下文
144	     * @return bool            合法返回 true，否则 false
145	     */
146	    bool CheckSrcBlockList(const LaunchParam &launchParam) const
147	    {
148	        auto &srcLocation = launchParam.GetInTensor(DIM_2);
149	        auto &cumSum = launchParam.GetInTensor(DIM_4);
150	
151	        MKI_CHECK(!CheckEmptyTensor(srcLocation), "3rd inTensor should not be null tensor ", return false);
152	        MKI_CHECK(!CheckEmptyTensor(cumSum), "5th inTensor should not be null tensor ", return false);
153	
154	        MKI_CHECK(srcLocation.desc.dtype == TENSOR_DTYPE_INT32, "src's dtype should be int32", return false);
155	        MKI_CHECK(cumSum.desc.dtype == TENSOR_DTYPE_INT32, "cumSum's dtype should be int32", return false);
156	
157	        MKI_CHECK(srcLocation.desc.dims == cumSum.desc.dims, "src&cumSum's shape should be same", return false);
158	        MKI_CHECK(srcLocation.desc.dims.size() == DIM_1, "src&&cumSum's dim num should be " << DIM_1, return false);
159	
160	        return true;
161	    }
162	    /**
163	     * @brief 检查 dst block 列表张量的合法性。
164	     *
165	     * - 非空
166	     * - dtype 为 int32
167	     * - 维度数为 1
168	     *
169	     * @param[in] launchParam  运行时上下文
170	     * @return bool            合法返回 true，否则 false
171	     */
172	    bool CheckDistBlockIndices(const LaunchParam &launchParam) const
173	    {
174	        auto &distLocation = launchParam.GetInTensor(DIM_3);
175	
176	        MKI_CHECK(!CheckEmptyTensor(distLocation), "4th inTensor should not be null tensor ", return false);
177	
178	        MKI_CHECK(distLocation.desc.dtype == TENSOR_DTYPE_INT32, "dist's dtype should be int32", return false);
179	
180	        MKI_CHECK(distLocation.desc.dims.size() == DIM_1, "dist's dim num should be " << DIM_1, return false);
181	
182	        return true;
183	    }
184	};
185	
186	REG_OPERATION(CustomizeBlockCopyOperation); // Operation注册
187	} // namespace AtbOps
